MODULE RcdFactorial;
IMPORT TextMappers, DevCommanders, StdLog;

PROCEDURE GetParams(VAR ps: ARRAY OF INTEGER);
VAR
	i: INTEGER;
	s: TextMappers.Scanner;
	p: DevCommanders.Par;
BEGIN
	p := DevCommanders.par;
	IF p # NIL THEN
		s.ConnectTo(p.text);s.SetPos(p.beg);
		s.Scan;i := 0;
		WHILE (i < LEN(ps)) & (s.type = TextMappers.int) DO
			ps[i] := s.int;INC(i);
			s.Scan
		END
	END
END GetParams;

PROCEDURE Factorial(i: LONGINT): LONGINT;
VAR
BEGIN
	IF i < 0 THEN i := -i  END;
	IF i < 2 THEN
		RETURN i
	ELSE
		RETURN i * Factorial(i - 1)
	END
END Factorial;

PROCEDURE ComputeRange*;
VAR
	i: INTEGER;
	ps: ARRAY 2 OF INTEGER;
BEGIN
	GetParams(ps);
	FOR i := ps[0] TO ps[1] DO
		StdLog.Int(i);StdLog.String("! =");StdLog.Int(Factorial(i));
		StdLog.Ln		
	END
END ComputeRange;

END RcdFactorial.

