pub fn factorial(comptime Num: type, n: i8) ?Num {
    return if (@typeInfo(Num) != .Int)
        @compileError("factorial called with non-integral type: " ++ @typeName(Num))
    else if (n < 0)
        null
    else calc: {
        var i: i8 = 1;
        var fac: Num = 1;
        while (i <= n) : (i += 1) {
            const tmp = @mulWithOverflow(fac, i);
            if (tmp[1] != 0)
                break :calc null; // overflow
            fac = tmp[0];
        } else break :calc fac;
    };
}

